// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Reverter receiver;

    function setUp() public {
        c = new MyContract();
        receiver = new Reverter();
        vm.deal(address(c), 10 ether);
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this)); // c.owner() == address(this) (deployer)
        vm.assume(actor != address(c));
        amount = bound(amount, 1, type(uint256).max);

        bool bad = false;
        vm.prank(actor);
        try c.sendTo(address(receiver), amount) {
            // non-owner call should not succeed, but success is also fine for the property below
        } catch (bytes memory reason) {
            // Rule: a non-owner caller's revert is the plain owner-check failure -> empty revert data,
            // never a transfer-related reason bubbled from the receiver.
            if (reason.length != 0) bad = true;
        }
        assertTrue(!bad, "non-owner revert must be the owner-check failure (empty reason)");
    }
}

contract Reverter {
    fallback() external payable {
        revert("no");
    }
}
